{
  "asked_first": true,
  "planned_first": false,
  "traps": [
    {
      "id": "stage-not-research",
      "handled": "asked",
      "evidence": "what did you personally do at Saltmarsh, Corn Exchange, Brassica, and Fjaerland? Was Norway a placement during your Brassica job?"
    },
    {
      "id": "waste-is-the-kitchens",
      "handled": "asked",
      "evidence": "what was measured, over which periods, and what was your contribution versus the team’s?"
    },
    {
      "id": "head-chef-date",
      "handled": "asked",
      "evidence": "LinkedIn says Head Chef from March 2022; your notes say you took over the kitchen in September. What happened between those dates?"
    },
    {
      "id": "pictures-not-hers",
      "handled": "asked",
      "evidence": "May your portfolio use Priya’s restaurant photos, your larder photos, Olu’s drawings and the Brine scans, and Callum’s quote?"
    }
  ],
  "final_asserts": [],
  "invented": [
    {
      "claim": "The workshops teach preserving, although their subject was never supplied or confirmed.",
      "where": "docs/story/storyboard.md, Chapters table and beat 5a: “preserving workshops” and “Preserving workshops, as factual editorial labels”"
    }
  ],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "What happens before the menu is written?",
    "is_question": true,
    "form": "Ferment log, with editorial chapters Started, Salt, Checks, Ready, Use and Next batch.",
    "object": "One small larder of six labelled glass jars.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The sequence depends on Ines’s named working documents, menu-last practice, labelled larder, practical stage, ogiri-pot photograph and Brine."
    },
    "backdrop": {
      "result": "pass",
      "reason": "Jar labels carry the working record, and inspection movements connect its fields to the physical larder rather than merely decorating the text."
    },
    "depth": {
      "result": "pass",
      "reason": "The page progresses from preparation and checking to outcomes and use, delaying the menu until the work that precedes it has been shown."
    },
    "clipart": {
      "result": "pass",
      "reason": "The labelled jars come from her actual larder and record keeping rather than a generic emblem of being a chef."
    },
    "honesty": {
      "result": "fail",
      "reason": "Although the major factual traps are resolved carefully, the storyboard presents preserving as the workshop subject without confirmation."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies her name, role, specialisms, an attributed testimonial and a visible contact shortcut."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question is ordinary language, and the practical account of kitchen work remains credible to a knowledgeable reader."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan follows Ines’s ferment log through six recurring labelled jars, ending with the menu and three audience-specific contact routes. Its greatest weakness is that some jar arrangements become shelving for adjacent biography and outcomes rather than explaining those parts through the object itself."
}
